  caseChoices.forEach(function(btn){
    btn.addEventListener('mouseenter', function(){
      caseChoices.forEach(function(o){ if (o !== btn) gsap.to(o, { opacity: 0.85, duration: 0.3, overwrite: 'auto' }); });
    });
    btn.addEventListener('mouseleave', function(){
      caseChoices.forEach(function(o){ gsap.to(o, { opacity: 1, duration: 0.3, overwrite: 'auto' }); });
    });
  });
}

/* ============================================================ §7 R5 showcasen (B2)
   Portar V3d:s measureCase/caseY exakt (index.html rad ~3248-3345):
   samma ankarformat, samma smoothstep-blandning mellan ankare, samma
   write-if-changed>=0.5px mot contentWindow.scrollTo. V3d körde detta ur
   en egen "akt"-motor (processens/caseens LERPADE cur); här driver GSAP
   ScrollTriggerns egen scrub-progress caseY direkt - ingen egen
   lerp-motor att portera, scrub:0.6 ger motsvarande eftersläpning. */
var SHOWCASE_DEFS = {
  calyx: { anchors: [ ['top', 0], ['#studio', 0], ['#studio + section', 0, 48, 700], ['#index', 0], ['#commission', 0] ] },
  horai: { anchors: [ ['top', 0], ['#hero-section + section', 0.30], ['#quote-section', 'center', -100, 700], ['#quote-section + section', 0], ['#reservations', -1], ['#reservations', 0] ] }
};
var CASES = {
  calyx: { key: 'calyx', el: document.getElementById('showcase-calyx'), iframe: document.getElementById('showcaseIframeCalyx'), anchors: SHOWCASE_DEFS.calyx.anchors, y: null, w: null, last: -1, lastRow: -1 },
  horai: { key: 'horai', el: document.getElementById('showcase-horai'), iframe: document.getElementById('showcaseIframeHorai'), anchors: SHOWCASE_DEFS.horai.anchors, y: null, w: null, last: -1, lastRow: -1 }
};
var activeCaseKey = 'calyx';
window.__CASES = CASES; /* dev hook for the verification suite */

/* R5 bugfix: pinning an ancestor of a live iframe makes GSAP's own
   pin-spacer wrap (on creation) and unwrap/rewrap (on every later
   revert-and-remeasure inside ScrollTrigger.refresh()) move that
   ancestor in the DOM - and moving an iframe element's ancestor makes
   the browser reload it. Confirmed by instrumenting the calyx iframe's
   own 'load' event: it fired twice on a single page load, a frame apart,
   matching two refresh() passes. A one-shot {once:true} listener caught
   only the first reload and kept a stale, detached contentWindow after
   the second - every anchor then clamped to 0 (writeCaseScroll() no-ops
   forever against a dead window). This listener is never removed, so
   every reload - however many happen - re-measures against the CURRENT
   contentWindow. */
Object.keys(CASES).forEach(function(key){
  var C = CASES[key];
  if (!C.iframe) return;
  C.iframe.addEventListener('load', function(){
    if (activeCaseKey === C.key) measureCase(C);
  });
});
var showcaseFrameWrap = document.getElementById('showcaseFrameWrap');
var showcaseSection = document.getElementById('showcase');
var showcaseST = null;

/* gate for safeRefresh() (declared above, near the Lenis wiring) - see
   that comment for why every refresh() in the file waits for this. */
(function watchShowcaseSettle(){
  var f = CASES.calyx.iframe;
  if (!f){ __showcaseIframeSettled = true; return; }
  if (f.getAttribute('src')){
    f.addEventListener('load', function once(){
      f.removeEventListener('load', once);
      requestAnimationFrame(function(){ requestAnimationFrame(function(){ __showcaseIframeSettled = true; }); });
    }, { once: true });
  } else {
    __showcaseIframeSettled = true;
  }
  /* fail-safe: never block real refreshes forever if 'load' is missed
     for any reason (e.g. a cached/instant load that fires before this
     listener attaches). */
  setTimeout(function(){ __showcaseIframeSettled = true; }, 2000);
})();

function scaleShowcaseFrame(){
  /* the iframe stays a real 1440x900 document (so the site renders at
     its own desktop layout, per spec "en 1440 px bred iframe"); a CSS
     transform:scale fits that fixed-size frame to whatever the cell's
     actual box is, sharp, no image re-sampling. */
  if (!showcaseFrameWrap) return;
  var r = showcaseFrameWrap.getBoundingClientRect();
  if (!r.width || !r.height) return;
  /* cover, not contain, at every breakpoint: scaling by width alone on
     the mobile (portrait, 56svh-tall) cell left most of the sticky area
     empty below a letterboxed sliver. Math.max fills the cell edge to
     edge on both axes (the wrap's own overflow:hidden crops the excess),
     same "sharp, filled cell" the spec asks for on desktop. */
  var scale = Math.max(r.width / 1440, r.height / 900);
  Array.prototype.forEach.call(showcaseFrameWrap.querySelectorAll('iframe'), function(f){
    gsap.set(f, { scale: scale, transformOrigin: 'top left' });
  });
}

function measureCase(C){
  var f = C.iframe, w = f && f.contentWindow, d = null;
  try { d = f && f.contentDocument; } catch (e) { d = null; }
  if (!w || !d || !d.documentElement) return false;
  /* R5 bugfix: measureCase briefly succeeded against the iframe's OWN
     still-about:blank document from the instant a new `src` is assigned
     (navigation hasn't swapped contentDocument yet) - a blank document's
     scrollHeight equals its own clientHeight, so max === 0 exactly
     (not negative), which slipped past a `max < 0` guard and produced
     every anchor's clamp collapsing to 0 (all six caseY() reads stuck
     at 0px). Require readyState:'complete' AND max > 0 (a real page's
     content should always exceed the frame height) so the caller's
     `if (!C.y) attach onLoad` fallback actually engages instead of
     "succeeding" against garbage. */
  if (d.readyState !== 'complete') return false;
  var ih = w.innerHeight, max = d.documentElement.scrollHeight - ih;
  if (!ih || max <= 0) return false;
  C.w = w;
  C.y = C.anchors.map(function(a){
    var el = a[0] === 'top' ? null : d.querySelector(a[0]);
    var t = el ? el.offsetTop : 0;
    var off = a[1] === 'center' ? (el ? (el.offsetHeight - ih) / 2 : 0) : a[1] * ih;
    if (a[2] && ih < (a[3] || Infinity)) off += a[2];
    return Math.max(0, Math.min(max, Math.round(t + off)));
  });
  return true;
}
function caseY(C, p){
  var n = C.y.length, k = Math.min(n - 1, Math.floor(p * n)), t = p * n - k;
  if (k === 0) return C.y[0];
  var u = Math.min(1, t / 0.45); u = u * u * (3 - 2 * u);
  return C.y[k - 1] + (C.y[k] - C.y[k - 1]) * u;
}
function writeCaseScroll(C, p){
  if (!C.y || !C.w) return;
  var y = caseY(C, p);
  if (Math.abs(y - C.last) >= 0.5){
    C.w.scrollTo({ top: y, left: 0, behavior: 'instant' });
    C.last = y;
  }
}
/* R6 §2: ledger/accordion, not a mask-reveal. Every row's heading is
   always in the DOM and always visible; only the ACTIVE row's body ever
   has a non-zero height, via the CSS grid-template-rows 0fr->1fr trick
   (.row-body / .row-body-inner, desktop/tablet only - the media query in
   the CSS keeps mobile's bodies permanently expanded, per spec). Class
   toggling only - the actual animation is a CSS transition, which is
   interruptible by construction (Emil's rule): scrolling back and forth
   across the same anchor boundary retargets smoothly instead of
   restarting from 0, because the browser is transitioning the CURRENT
   computed track size, not replaying a keyframe. */
function setRowState(C, k){
  if (C.lastRow === k) return;
  C.lastRow = k;
  var rows = C.el.querySelectorAll('.showcase-row');
  rows.forEach(function(row, i){
    row.classList.toggle('is-active', i === k);
    row.classList.toggle('is-past', i < k);
    row.classList.toggle('is-upcoming', i > k);
  });
}
function updateShowcase(C, p){
  writeCaseScroll(C, p);
  var n = C.anchors.length;
  var k = Math.min(n - 1, Math.floor(Math.max(0, Math.min(1, p)) * n));
  setRowState(C, k);
}

function setupDesktopEngine(C){
  /* the ScrollTrigger is created SYNCHRONOUSLY every time, regardless of
     whether the iframe has finished loading yet: `end` only depends on
     C.anchors.length (static per case), never on the measured y-values,
     so there is no need to wait. Creating it async (only once measureCase
     succeeded) put it out of page-creation-order relative to every
     ScrollTrigger below it, and a later ScrollTrigger.refresh() tried to
     revert pins in creation order against a DOM that no longer matched -
     "insertBefore ... no longer a child" (gsap-scrolltrigger skill: keep
     creation order == page order). measureCase/writeCaseScroll no-op
     safely (guarded on C.y) until the iframe's own 'load' backfills it. */
  if (showcaseST){ showcaseST.kill(); showcaseST = null; }
  measureCase(C);
  /* the persistent 'load' listener attached in setupCaseLoadListeners()
     (below) backfills C.y/C.w whenever the iframe (re)loads - including
     reloads GSAP's own pin-spacer wrap/unwrap triggers on the ancestor,
     which a one-shot {once:true} listener here would miss the second
     time, leaving C.w pointing at a stale, detached contentWindow. */
  scaleShowcaseFrame();
  var n = C.anchors.length;
  showcaseST = ScrollTrigger.create({
    trigger: '#showcase', start: 'top top', end: '+=' + (n * window.innerHeight),
    pin: '.showcase-stage', pinSpacing: true, scrub: 0.6,
    onUpdate: function(self){ updateShowcase(C, self.progress); },
    onRefresh: function(self){ updateShowcase(C, self.progress); }
  });
  updateShowcase(C, 0);
}

function activateCase(key, opts){
  opts = opts || {};
  var isNewSelection = key !== activeCaseKey;
  activeCaseKey = key;
  caseChoices.forEach(function(btn){ btn.setAttribute('aria-pressed', btn.getAttribute('data-case') === key ? 'true' : 'false'); });
  Object.keys(CASES).forEach(function(k){
    var C = CASES[k];
    var show = k === key;
    C.el.style.display = show ? '' : 'none';
    C.el.toggleAttribute('inert', !show);
    C.iframe.style.display = show ? '' : 'none';
  });
  var C = CASES[key];
  if (!C.iframe.src && C.iframe.hasAttribute('data-showcase-src')){
    C.iframe.src = C.iframe.getAttribute('data-showcase-src');
    C.iframe.removeAttribute('data-showcase-src');
  }
  if (window.innerWidth >= 768) setupDesktopEngine(C);
  else measureCase(C);
  if (isNewSelection || opts.forceRise) {
    C.lastRow = -1;
    updateShowcase(C, 0);
  }
  safeRefresh();
  if (opts.scroll !== false && lenis && lenis.scrollTo) lenis.scrollTo('#showcase', { duration: 1.2 });
}

caseChoices.forEach(function(btn){
  btn.addEventListener('click', function(){ activateCase(btn.getAttribute('data-case')); });
});

gsap.matchMedia().add({ isDesktop: '(min-width:768px)', isMobile: '(max-width:767px)' }, function(context){
  if (context.conditions.isDesktop){
    setupDesktopEngine(CASES[activeCaseKey]);
    return function(){ if (showcaseST){ showcaseST.kill(); showcaseST = null; } };
  }
  /* mobile (§B2): no pin - the frame sits position:sticky (CSS) while
     rows scroll under it; each row's onEnter/onEnterBack tweens the
     site's own inner scroll to that row's anchor over 0.6s.
     R5 bugfix: scaleShowcaseFrame() was only ever called from
     setupDesktopEngine() (the isDesktop branch) - on mobile the iframe
     kept its native 1440x900 box with no scale transform at all, so the
     sticky cell showed an unscaled, cropped sliver of the top-left
     corner instead of the whole page shrunk to fit. */
  scaleShowcaseFrame();
  Object.keys(CASES).forEach(function(k){ measureCase(CASES[k]); });
  var mobileTriggers = [];
  Object.keys(CASES).forEach(function(k){
    var C = CASES[k];
    var rows = C.el.querySelectorAll('.showcase-row');
    rows.forEach(function(row, i){
      mobileTriggers.push(ScrollTrigger.create({
        trigger: row, start: 'top 70%',
        onEnter: function(){ tweenCaseTo(C, i); },
        onEnterBack: function(){ tweenCaseTo(C, i); }
      }));
    });
  });
  return function(){ mobileTriggers.forEach(function(t){ t.kill(); }); };
});

function tweenCaseTo(C, i){
  if (!C.y && !measureCase(C)) return;
  var target = C.y[i];
  var proxy = { v: C.last >= 0 ? C.last : target };
  gsap.to(proxy, {
    v: target, duration: 0.6, ease: 'power2.out',
    onUpdate: function(){
      if (C.w && Math.abs(proxy.v - C.last) >= 0.5){ C.w.scrollTo({ top: proxy.v, left: 0, behavior: 'instant' }); C.last = proxy.v; }
    }
  });
  setRowState(C, i);
}

