1318	
1319	  /* C: the active step index, from the SAME progress caseY reads, gated to
1320	     the crossfade's own 25%/25% timing so the outgoing step is still
1321	     flagged active while it fades and the incoming one only takes over
1322	     once its own fade-in starts (SHOWCASE-SPEC §C: "tonas ut i första 25%",
1323	     "tonas in i nästa 25%"). */
1324	  function activeStepIndexFor(n, p){
1325	    var pp = Math.max(0, Math.min(1, p)), kf = pp * n;
1326	    var k = Math.min(n - 1, Math.floor(kf));
1327	    if (k === 0) return 0;
1328	    var t = kf - k;
1329	    return t < 0.25 ? k - 1 : k;
1330	  }
1331	  function pad2(n){ return (n < 10 ? '0' : '') + n; }
1332	
1333	  /* desktop only: toggles aria-hidden/visibility once per step change (not
1334	     per frame, per spec) and updates the mono counter. The crossfade itself
1335	     is C.tl (built in buildStepTimelines), scrubbed by the same pin. */
1336	  function setStepState(C, p){
1337	    var n = C.anchors.length;
1338	    var idx = activeStepIndexFor(n, p);
1339	    if (C.lastStep === idx) return;
