1350	  function writeTrackFill(p){
1351	    var pp = Math.max(0, Math.min(1, p));
1352	    Object.keys(CASES).forEach(function(k){
1353	      var fill = CASES[k].trackFill;
1354	      if (fill) fill.style.transform = 'scaleX(' + pp + ')';
1355	    });
