1363	
1364	  /* C: one GSAP timeline per case, paused, progress-driven (never played) -
1365	     0..1 on the timeline maps 1:1 to the pin's own progress. Each step k
1366	     (1..n-1) fades out step k-1 (opacity 1->0, y 0->-12px) over the
1367	     segment's first 25%, then fades in step k (opacity 0->1, y 12->0) over
1368	     the next 25%; the remaining 50% (the segment's dwell half, matching B)
1369	     is untouched, so the step reads fully still for >=40vh. Only opacity
1370	     and transform animate. */
1371	  function buildStepTimelines(){
1372	    Object.keys(CASES).forEach(function(key){
1373	      var C = CASES[key];
1374	      var box = C.el.querySelector('.showcase-rows');
1375	      C.head = C.el.querySelector('.showcase-head');
1376	      C.box = box;
