1380	      C.textEls = C.steps.map(function(row){ return row.querySelector('.showcase-row-text'); });
1381	      var n = C.anchors.length;
1382	      gsap.set(C.textEls, { opacity: 0, y: 12 });
1383	      gsap.set(C.textEls[0], { opacity: 1, y: 0 });
1384	      C.steps.forEach(function(row, i){
1385	        row.classList.toggle('is-active', i === 0);
1386	        row.setAttribute('aria-hidden', i === 0 ? 'false' : 'true');
1387	        row.style.visibility = i === 0 ? '' : 'hidden';
1388	      });
1389	      C.lastStep = 0;
1390	      var tl = gsap.timeline({ paused: true });
1391	      for (var k = 1; k < n; k++){
1392	        var segStart = k / n, outDur = 0.25 / n, inDur = 0.25 / n;
1393	        tl.to(C.textEls[k - 1], { opacity: 0, y: -12, duration: outDur, ease: 'power2.out' }, segStart);
1394	        tl.to(C.textEls[k], { opacity: 1, y: 0, duration: inDur, ease: 'power2.out' }, segStart + outDur);
1395	      }
1396	      C.tl = tl;
1397	    });
1398	  }
1399	
1400	  /* A: the pin is created ONCE here, at init, and never killed/recreated -
1401	     a click only swaps which C activeCaseKey points at (grundorsak 1).
1402	     The pin's own length is FIXED (6 segments x 75vh) regardless of which
1403	     case is active or how many anchors it has, so a casebyte never needs a
1404	     geometry-changing refresh() (grundorsak 6); Calyx's 5 anchors simply
1405	     divide that same fixed length into 5 stops instead of 6 (see caseY). */
1406	  function setupDesktopEngine(){
