1416	      onUpdate: function(self){ updateShowcase(CASES[activeCaseKey], self.progress); writeTrackFill(self.progress); },
1417	      onRefresh: function(self){ updateShowcase(CASES[activeCaseKey], self.progress); writeTrackFill(self.progress); }
1418	    });
