1496	    scaleShowcaseFrame();
1497	    Object.keys(CASES).forEach(function(k){ measureCase(CASES[k]); });
1498	    var mobileTriggers = [];
1499	    Object.keys(CASES).forEach(function(k){
1500	      var C = CASES[k];
1501	      var rows = Array.prototype.slice.call(C.el.querySelectorAll('.showcase-row'));
1502	      var textEls = rows.map(function(row){ return row.querySelector('.showcase-row-text'); });
1503	      C.mobileTextEls = textEls;
