1509	          onEnter: function(){ tweenCaseTo(C, i); setMobileRowOpacity(textEls, i); },
1510	          onEnterBack: function(){ tweenCaseTo(C, i); setMobileRowOpacity(textEls, i); }
1511	        }));
1512	      });
1513	    });
1514	    return function(){ mobileTriggers.forEach(function(t){ t.kill(); }); };
1515	  });
