1520	    var proxy = { v: C.last >= 0 ? C.last : target };
1521	    gsap.to(proxy, {
1522	      v: target, duration: 0.6, ease: 'power2.out',
1523	      onUpdate: function(){
1524	        if (C.w && Math.abs(proxy.v - C.last) >= 0.5){ C.w.scrollTo({ top: proxy.v, left: 0, behavior: 'instant' }); C.last = proxy.v; }
1525	      }
