1557	  var prisA = document.querySelector('.pris-tier-a');
1558	  var prisB = document.querySelector('.pris-tier-b');
1559	  var prisTl = gsap.timeline({
1560	    defaults: { duration: 0.6, ease: 'power3.out' },
1561	    scrollTrigger: { trigger: '.pris-bento', start: 'top 78%', toggleActions: 'play none none reverse' }
1562	  });
