1564	  if (prisA) prisTl.fromTo(prisA, { yPercent: -18, autoAlpha: 0 }, { yPercent: 0, autoAlpha: 1 }, 0.08);
1565	  if (prisB) prisTl.fromTo(prisB, { yPercent: 18, autoAlpha: 0 }, { yPercent: 0, autoAlpha: 1 }, 0.16);
1566	
1567	  function countUp(el, targetNumber, originalText){
1568	    var proxy = { v: 0 };
1569	    gsap.to(proxy, {
1570	      v: targetNumber, duration: 1.1, ease: 'power2.out',
1571	      scrollTrigger: { trigger: el, start: 'top 85%', once: true },
1572	      onUpdate: function(){
1573	        var whole = Math.round(proxy.v).toString();
