    page3.evaluate("window.__lenis.scrollTo('#kontakt', {immediate:true})")
    page3.wait_for_timeout(400)
    result["jump_to_kontakt_shows_back"] = not page3.evaluate(
        "document.getElementById('kontaktCardBack').hasAttribute('inert')"
    )
