    if not y_expected:
        return {"found_pin": True, "anchors_measured": False}
    n = len(y_expected)
    diffs = []
    # SHOWCASE-SPEC.md §D2 (V3g): the old accordion's `.is-active` row
    # (a per-case height reveal) is gone - desktop now shows exactly one
    # step in the crossfading box at a time (grid-stacked, opacity/
    # aria-hidden/visibility driven from the pin's progress, never a
    # class-toggle height). At each sampled anchor point this reads
    # which step the box currently shows (aria-hidden="false") and
    # checks it against the step the anchor's own index implies.
    step_matches = []
    for i in range(n):
        frac = (i + 0.999) / n
        y = pin["start"] + (pin["end"] - pin["start"]) * frac
        page.evaluate(f"window.__lenis.scrollTo({y}, {{immediate:true}})")
        page.wait_for_timeout(120)
        actual = page.evaluate(f"document.getElementById('{iframe_id}').contentWindow.scrollY")
        diffs.append(round(abs(actual - y_expected[i]), 2))
        visible_step = page.evaluate(
            f"""() => {{
                const row = document.querySelector('#showcase-{key} .showcase-row[aria-hidden="false"]');
                return row ? parseInt(row.dataset.row, 10) : null;
            }}"""
        )
        step_matches.append({"anchor": i, "visible_step": visible_step, "matches": visible_step == i})
    return {
        "found_pin": True,
        "anchors_measured": True,
        "expected": [round(v) for v in y_expected],
        "diffs_px": diffs,
        "all_within_2px": all(d <= 2 for d in diffs),
        "box_step_matches_anchor": step_matches,
        "box_step_all_match": all(m["matches"] for m in step_matches),
    }

